final class app_control_s extends ffi.Opaque {}

/// @brief Enumeration for the application control error.
/// @since_tizen 2.3
abstract class app_control_error_e {
  /// < Successful
  static const int APP_CONTROL_ERROR_NONE = 0;

  /// < Invalid parameter
  static const int APP_CONTROL_ERROR_INVALID_PARAMETER = -22;

  /// < Out of memory
  static const int APP_CONTROL_ERROR_OUT_OF_MEMORY = -12;

  /// < The application is not found
  static const int APP_CONTROL_ERROR_APP_NOT_FOUND = -17825759;

  /// < Specified key is not found
  static const int APP_CONTROL_ERROR_KEY_NOT_FOUND = -126;

  /// < Key is not available
  static const int APP_CONTROL_ERROR_KEY_REJECTED = -129;

  /// < Invalid data type
  static const int APP_CONTROL_ERROR_INVALID_DATA_TYPE = -17825758;

  /// < The application cannot be launched now
  static const int APP_CONTROL_ERROR_LAUNCH_REJECTED = -17825757;

  /// < Permission denied
  static const int APP_CONTROL_ERROR_PERMISSION_DENIED = -13;

  /// < Internal launch error
  static const int APP_CONTROL_ERROR_LAUNCH_FAILED = -17825756;

  /// < Time out
  static const int APP_CONTROL_ERROR_TIMED_OUT = -1073741823;

  /// < IO error
  static const int APP_CONTROL_ERROR_IO_ERROR = -5;
}

/// @brief Enumeration for the application control result.
/// @since_tizen 2.3
/// @see app_control_enable_app_started_result_event()
abstract class app_control_result_e {
  /// < Callee application launched actually (Since 2.4)
  static const int APP_CONTROL_RESULT_APP_STARTED = 1;

  /// < Operation succeeded
  static const int APP_CONTROL_RESULT_SUCCEEDED = 0;

  /// < Operation failed by the callee
  static const int APP_CONTROL_RESULT_FAILED = -1;

  /// < Operation canceled by the platform
  static const int APP_CONTROL_RESULT_CANCELED = -2;
}

/// @brief Enumeration for the application control launch mode.
/// @since_tizen 2.4
abstract class app_control_launch_mode_e {
  /// < Prefer to launch an application as single mode
  static const int APP_CONTROL_LAUNCH_MODE_SINGLE = 0;

  /// < Prefer to launch an application as group mode
  static const int APP_CONTROL_LAUNCH_MODE_GROUP = 1;
}

